import{WIDTH,HEIGHT,SHRINES,NPCS,BUILDINGS,initialState,sanitiseState,region,move,grantRelic,balanced,memoryCorrect,purchaseUpgrade,SHARDS}from'./engine.mjs';
const $=s=>document.querySelector(s),c=$('#world'),ctx=c.getContext('2d'),modal=$('#modal'),keys=new Set(),SAVE='bukham-shellbound-v1';
let saved=null;try{saved=JSON.parse(localStorage.getItem(SAVE));}catch{}let state=sanitiseState(saved),running=false,paused=false,coop=false,sound=false,audio=null,players=[],camera={x:0,y:0},cw=900,ch=700,zoom=1,clock=0,last=0,particles=[],pulses=[],near=null,toasts=0,storm=null,dialogVersion=0,saveClock=0,clickTarget=null;
const colours=['#5ddbcc','#f6c35e','#d896ef','#f58a73'];const zones=['LANTERN MARKET','RIVER OF ECHOES','THE SKY CITADEL'];
const wisps=Array.from({length:8},(_,i)=>({x:1300+(i%4)*430,y:480+Math.floor(i/4)*650,ox:1300+(i%4)*430,oy:480+Math.floor(i/4)*650,stun:0,phase:i*1.8}));
if(saved)$('#continue').hidden=false;
function save(){if(players[0]){state.x=players[0].x;state.y=players[0].y;}try{localStorage.setItem(SAVE,JSON.stringify(state));}catch{}}
function tone(freq=440,duration=.1){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toasts);toasts=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function burst(x,y,col,n=18){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=30+Math.random()*90;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.6+Math.random()*.7,max:1.3,col});}}
function show(label,html){dialogVersion++;keys.clear();clickTarget=null;$('#modalLabel').textContent=label;$('#modalContent').innerHTML=html;if(!modal.open)modal.showModal();}
function close(){dialogVersion++;modal.close();keys.clear();c.focus();}
$('#closeModal').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close();});
function newPlayer(x,y,i){return{x,y,i,energy:100,hearts:3,inv:0,dash:0,cool:0,pulseCool:0,dx:1,dy:0};}
function start(two,reset=false){coop=two;if(reset)state=initialState();players=[newPlayer(state.x,state.y,0)];if(coop)players.push(newPlayer(state.x-35,state.y+30,1));running=true;paused=false;$('#landing').hidden=true;$('#game').hidden=false;$('#mode').textContent=coop?'Local co-op · 2 players':'Solo expedition';$('#pause').textContent='Pause';resize();updateHUD();save();c.focus();toast('Find the glowing shrine. Collect sky shards along the way.');}
function choose(two){if(saved){show('START AN EXPEDITION','<h2>Your realm is waiting.</h2><p>Continue your saved quest, or begin a new expedition. A new expedition replaces progress stored on this device.</p><div class="dialog-actions"><button class="primary" id="resume">Continue quest</button><button id="new">Start fresh</button></div>');$('#resume').onclick=()=>{close();start(two);};$('#new').onclick=()=>{close();saved=null;start(two,true);};}else start(two,true);}
$('#solo').onclick=()=>choose(false);$('#coop').onclick=()=>choose(true);$('#continue').onclick=()=>start(false);$('#home').onclick=()=>{save();saved=state;running=false;$('#game').hidden=true;$('#landing').hidden=false;$('#continue').hidden=false;};
function resize(){const r=c.getBoundingClientRect();cw=r.width;ch=r.height;const d=Math.min(devicePixelRatio||1,2);c.width=cw*d;c.height=ch*d;ctx.setTransform(d,0,0,d,0,0);zoom=cw<550?.65:.88;}
window.addEventListener('resize',resize);window.addEventListener('blur',()=>{keys.clear();clickTarget=null;});document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden&&running){paused=true;$('#pause').textContent='Resume';save();}});
function dash(p){if(p.cool>0||p.energy<25)return;p.energy-=25;p.dash=.2;p.cool=.8;burst(p.x,p.y,skin(p),8);tone(660,.08);}
function pulse(p){if(p.pulseCool>0||p.energy<18)return;p.energy-=18;p.pulseCool=.8;pulses.push({x:p.x,y:p.y,r:0,life:.6});for(const w of wisps)if(Math.hypot(w.x-p.x,w.y-p.y)<180){w.stun=3;burst(w.x,w.y,'#c599ff',10);}tone(220,.22);collect(p,135);}
function skin(p){return p.i?'#f6a3cf':state.skin;}
function closest(p){let best=null,dist=85;for(const obj of [...NPCS.map(n=>({...n,kind:'npc'})),...SHRINES.map(n=>({...n,kind:'shrine'})),{x:2820,y:1040,name:'The Broken Sky Gate',kind:'gate'}]){const d=Math.hypot(p.x-obj.x,p.y-obj.y);if(d<dist){best=obj;dist=d;}}return best;}
function interact(p=players[0]){if(!p||modal.open||paused)return;const n=closest(p);if(!n){toast('Move closer to a character, glowing shrine or sky gate.');return;}if(n.kind==='npc'){if(!state.visited.includes(n.name))state.visited.push(n.name);show('MEET THE REALM',`<h2>${n.name}</h2><p>${n.text}</p><div class="dialog-actions"><button class="primary" id="dialogDone">Keep exploring →</button></div>`);$('#dialogDone').onclick=close;save();}else if(n.kind==='gate'){if(state.relics.length<3){toast('Restore all three echoes to awaken the sky gate.');return;}if(state.won){show('REALM RESTORED','<div class="reward">◈</div><h2>The sky remembers you.</h2><p>You have completed this expedition. Keep exploring for shards, or start a fresh adventure from the title screen.</p>');return;}show('FINAL CHALLENGE','<h2>Hold back the storm.</h2><p>Survive for 25 seconds while the gate rebuilds. Move away from the red circles before they strike. Dash between danger zones and pulse the wisps away.</p><p>Your relics are safe if you need another try.</p><button class="primary" id="stormStart">Begin the storm trial</button>');$('#stormStart').onclick=()=>{close();storm={time:25,spawn:0,hazards:[]};players.forEach((p,i)=>{p.x=2780+i*60;p.y=1000;p.hearts=3;p.energy=100;});toast('Storm trial started. Keep moving!');};}else if(state.relics.includes(n.id)){toast('This echo is restored. Its light guides the realm.');}else if(n.id==='memory')memoryTrial();else if(n.id==='balance')balanceTrial();else wisdomTrial();}
function reward(id){if(!grantRelic(state,id))return;save();updateHUD();const n=SHRINES.find(s=>s.id===id);burst(n.x,n.y,'#f6c35e',45);tone(880,.3);show('ECHO RESTORED',`<div class="reward">◈</div><h2>${n.name}</h2><p>You restored an echo and earned <strong>15 sky shards</strong>. ${state.relics.length===3?'The broken sky gate is ready. Find it in the east.':'A bridge has awakened. Follow the golden path east.'}</p><button class="primary" id="claim">Return to the adventure →</button>`);$('#claim').onclick=close;}
function memoryTrial(){const seq=[0,2,1,3,2];let input=[],watching=false;show('TRIAL 01 · THE LANTERN MARKET','<h2>The lanterns remember.</h2><p>Watch five flashes. Repeat them in the same order. The symbols and sounds help you remember.</p><div class="puzzle-grid">'+['◈','☀','≈','✦'].map((s,i)=>`<button data-note="${i}" aria-label="Lantern ${i+1}">${s}</button>`).join('')+'</div><p class="feedback" id="feedback">Press “Watch sequence” to begin.</p><div class="dialog-actions"><button class="primary" id="watch">Watch sequence</button></div>');const version=dialogVersion;let ready=false;$('#watch').onclick=async()=>{if(watching)return;input=[];ready=false;watching=true;$('#watch').disabled=true;$('#feedback').textContent='Watch carefully…';for(const n of seq){if(dialogVersion!==version)return;const b=$(`[data-note="${n}"]`);b.classList.add('lit');tone(300+n*130,.2);await delay(550);if(dialogVersion!==version)return;b.classList.remove('lit');await delay(180);}if(dialogVersion!==version)return;watching=false;ready=true;$('#watch').disabled=false;$('#feedback').textContent='Your turn. Repeat the five symbols.';};document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{if(!ready||watching)return;const n=Number(b.dataset.note);tone(300+n*130,.15);input.push(n);if(n!==seq[input.length-1]){ready=false;$('#feedback').textContent='A different echo. Watch again and try once more.';return;}$('#feedback').textContent=`${input.length} / 5 echoes matched`;if(memoryCorrect(input,seq))reward('memory');});}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function balanceTrial(){let v=[0,0,0];show('TRIAL 02 · RIVER OF ECHOES','<h2>Enough for everyone.</h2><p>Three travelling crews need supplies. You have 12 baskets. Give every crew the same share, using all 12.</p><div class="share-grid">'+['River crew','Sky crew','Market crew'].map((s,i)=>`<div class="share-card">${s}<b id="share${i}">0</b><button data-minus="${i}" aria-label="Remove basket from ${s}">−</button><button data-plus="${i}" aria-label="Add basket to ${s}">+</button></div>`).join('')+'</div><p class="feedback" id="feedback">12 baskets remaining</p><button class="primary" id="shareCheck">Seal the agreement</button>');const render=()=>{v.forEach((x,i)=>$('#share'+i).textContent=x);$('#feedback').textContent=`${12-v.reduce((a,b)=>a+b,0)} baskets remaining`;};document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{if(v.reduce((a,b)=>a+b,0)<12)v[+b.dataset.plus]++;render();tone(540,.08);});document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{const i=+b.dataset.minus;v[i]=Math.max(0,v[i]-1);render();});$('#shareCheck').onclick=()=>{if(balanced(v))reward('balance');else $('#feedback').textContent='Use every basket, and give each crew an equal share.';};}
function wisdomTrial(){let step=0;const questions=[['A quiet traveller notices a safer path. What do you do?',['Listen and check their idea.','Ignore them because they are new.','Pretend their idea was yours.'],0],['You discover a hidden shortcut in a team race. What is fair?',['Hide it and claim you ran faster.','Ask the organiser whether the route is allowed.','Move the signs so others get lost.'],1],['The feast is for everyone, but you arrive first. What do you do?',['Take every plate before anyone notices.','Rename yourself “Everyone”.','Take a fair share and leave enough for others.'],2]];const draw=()=>{const q=questions[step];show('TRIAL 03 · THE SKY CITADEL',`<h2>Wisdom is a choice.</h2><p>Choice ${step+1} of 3</p><p>${q[0]}</p>${q[1].map((s,i)=>`<button class="choice" data-answer="${i}">${s}</button>`).join('')}<p class="feedback" id="feedback"></p>`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(+b.dataset.answer!==q[2]){$('#feedback').textContent='Think about whose trust this choice might affect. Try again.';tone(180,.1);return;}step++;if(step===3)reward('wisdom');else draw();});};draw();}
function updateHUD(){const n=state.relics.length;$('#coins').textContent=state.coins;$('#relicCount').textContent=`${n} / 3`;$('#rank').textContent=state.won?'Keeper of the sky':['Shell seeker','Echo runner','River guardian','Sky challenger'][n];$('#relicList').innerHTML=SHRINES.map(s=>`<div class="relic ${state.relics.includes(s.id)?'done':''}"><b>${state.relics.includes(s.id)?'◈':'◇'}</b><div>${s.name.replace('Echo of ','')}<small>${state.relics.includes(s.id)?'RESTORED':zones[s.region]}</small></div></div>`).join('');$('#questTitle').textContent=state.won?'The realm is restored':['Follow the lanterns','Cross the river bridge','Reach the sky shrine','Awaken the sky gate'][n];$('#questText').textContent=state.won?'Explore, collect the remaining shards and show a friend the realm.':['Find the glowing shrine north-east of the market. E opens its trial.','Head east across the first bridge. The next shrine is south of the river path.','Cross the second bridge, then head north-east to the final shrine.','Find the great gate in the eastern citadel. Survive its storm trial.'][n];$('#questProgress').style.width=`${state.won?100:n*25}%`;}
function controls(){show('HOW TO PLAY','<h2>Your adventure, your way.</h2><div class="control-table"><div><h3>Player 1</h3><p><kbd>W A S D</kbd> move<br><kbd>E</kbd> talk / trial<br><kbd>Shift</kbd> dash<br><kbd>Space</kbd> shell pulse</p></div><div><h3>Player 2 / solo alternative</h3><p><kbd>Arrow keys</kbd> move<br><kbd>Enter</kbd> interact<br><kbd>/</kbd> dash<br><kbd>.</kbd> pulse</p></div></div><p>Click or tap the ground to guide Player 1. Avoid buildings and waterways; bridges cross at the middle path. In co-op, stay within 420 steps of your partner. Both players share relics and shards.</p><p><kbd>J</kbd> journal · <kbd>M</kbd> map · <kbd>Escape</kbd> pause. Touch controls appear on smaller screens. Progress saves on this browser. Sound starts off.</p><div class="dialog-actions"><button class="primary" id="gotit">Let’s go</button><button id="helpMap">World map</button><button id="helpJournal">Journal</button><button id="helpStyle">Style</button></div>');$('#gotit').onclick=close;$('#helpMap').onclick=worldMap;$('#helpJournal').onclick=journal;$('#helpStyle').onclick=()=>$('#wardrobe').click();}
$('#help').onclick=controls;$('#pause').onclick=()=>{paused=!paused;keys.clear();$('#pause').textContent=paused?'Resume':'Pause';save();};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'Sound on':'Sound off';tone(550,.15);};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#game').requestFullscreen();}catch{toast('Full screen is unavailable in this browser.');}};
function journal(){show('QUEST JOURNAL','<h2>The sky is coming apart.</h2><p>Restore three echoes and survive the storm to reconnect the realm. Take your time: there is no deadline.</p>'+SHRINES.map(s=>`<div class="journal-item"><strong>${state.relics.includes(s.id)?'✓':'◇'} ${s.name}</strong><p>${['Repeat a sequence of five lanterns.','Share twelve baskets fairly between three crews.','Make three choices that build trust.'][s.region]}</p></div>`).join('')+`<footer>${state.visited.length} / ${NPCS.length} characters met · ${state.collected.length} / ${SHARDS.length} shards discovered<br>Solo and shared-keyboard co-op are playable. Online rooms are not connected.</footer>`);}
$('#journal').onclick=journal;
function worldMap(){show('REALM MAP','<h2>Three districts. One journey.</h2>'+zones.map((z,i)=>`<div class="map-card"><strong>0${i+1} · ${z}</strong><p>${['Western district. Start at the market and find the shrine to the north-east.','Central district. Cross the first bridge; the sharing shrine is south of the path.','Eastern district. Wisdom shrine to the north; final sky gate to the east.'][i]}</p><small>${i===0||state.relics.includes(i===1?'memory':'balance')?'PATH OPEN':'RESTORE THE PREVIOUS ECHO TO OPEN THE BRIDGE'}</small></div>`).join('')+'<p>The main east–west path crosses both bridges. Glowing diamonds mark shrines. The compass points to your next objective.</p>');}$('#map').onclick=worldMap;
$('#wardrobe').onclick=()=>{show('YOUR LOADOUT','<h2>Make the journey yours.</h2><p>Choose your explorer’s accent colour. All colours are unlocked.</p><div class="swatches">'+colours.map(col=>`<button data-skin="${col}" class="${state.skin===col?'selected':''}" style="background:${col};color:#14232a">◈</button>`).join('')+`</div><div class="map-card"><strong>Windweave boots</strong><p>Move 15% faster. Earned with 20 sky shards from exploration. No payments.</p><button id="upgrade" ${state.upgrade?'disabled':''}>${state.upgrade?'Equipped':'Unlock · 20 shards'}</button></div><p class="feedback" id="feedback"></p>`);document.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{state.skin=b.dataset.skin;document.querySelectorAll('[data-skin]').forEach(x=>x.classList.toggle('selected',x===b));save();});$('#upgrade').onclick=()=>{if(purchaseUpgrade(state)){$('#upgrade').textContent='Equipped';$('#upgrade').disabled=true;save();updateHUD();tone(880,.2);}else $('#feedback').textContent='Explore for more sky shards. You need 20.';};};
$('#about').onclick=()=>show('BUKHAM PLAY · CONCEPT & SCOPE','<h2>A world built around wit.</h2><p>Shellbound is an original fantasy inspired by Nigerian tortoise storytelling, including Yoruba Ìjàpá and Igbo Mbe traditions. It is not a historical reconstruction or a claim that different African cultures are interchangeable.</p><p>This playable prototype includes exploration, three trials, collectible shards, upgrades, a final storm challenge and two-player local co-op. Characters are scripted NPCs, not online players.</p><p>The larger concept is a social adventure with shared hubs and cooperative expeditions. Live online rooms, accounts, moderation and server-verified progression require a separate production backend.</p><p>Created for BUKHAM Systems. Concept artwork is AI-generated. Gameplay uses an original illustrated 2D map.</p><p><a href="studio.html" style="color:#5ddbcc">Read the multiplayer development brief →</a></p>');
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','/'].includes(e.key)&&running&&!modal.open)e.preventDefault();if(modal.open)return;if(!running)return;if(e.key==='Escape'){$('#pause').click();return;}if(paused)return;keys.add(e.key.toLowerCase());if(e.repeat)return;if(e.key.toLowerCase()==='e')interact();if(e.key==='Enter')interact(players[coop?1:0]);if(e.key==='Shift')dash(players[0]);if(e.key==='/')dash(players[coop?1:0]);if(e.key===' ')pulse(players[0]);if(e.key==='.')pulse(players[coop?1:0]);if(e.key.toLowerCase()==='j')journal();if(e.key.toLowerCase()==='m')worldMap();});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);}
$('#touchDash').onclick=()=>dash(players[0]);$('#touchPulse').onclick=()=>pulse(players[0]);$('#touchInteract').onclick=()=>interact();$('#interact').onclick=()=>interact();c.onpointerdown=e=>{if(paused||modal.open)return;const r=c.getBoundingClientRect();clickTarget={x:(e.clientX-r.left-cw/2)/zoom+camera.x,y:(e.clientY-r.top-ch/2)/zoom+camera.y};c.focus();};
function collect(p,r=32){for(const s of SHARDS)if(!state.collected.includes(s.id)&&Math.hypot(s.x-p.x,s.y-p.y)<r){state.collected.push(s.id);state.coins++;burst(s.x,s.y,'#f6c35e',8);tone(800+Math.random()*200,.08);updateHUD();save();}}
function damage(p){if(p.inv>0)return;p.hearts--;p.inv=2;burst(p.x,p.y,'#f58a73',15);tone(140,.17);if(p.hearts<=0){const zone=region(p.x);p.x=[270,1240,2210][zone];p.y=950;p.hearts=3;p.energy=100;if(storm){storm=null;toast('The storm scattered. Your relics are safe. Return to the gate to retry.');}else toast('The realm caught you. Restored at the district checkpoint.');}}
function update(dt){clock+=dt;state.seconds+=dt;saveClock+=dt;if(saveClock>4){save();saveClock=0;}for(const p of players){p.inv=Math.max(0,p.inv-dt);p.cool=Math.max(0,p.cool-dt);p.pulseCool=Math.max(0,p.pulseCool-dt);p.dash=Math.max(0,p.dash-dt);p.energy=Math.min(100,p.energy+dt*12);let dx=0,dy=0;if(p.i===0){dx=(keys.has('d')?1:0)-(keys.has('a')?1:0);dy=(keys.has('s')?1:0)-(keys.has('w')?1:0);}if(p.i===1||!coop){dx+=(keys.has('arrowright')?1:0)-(keys.has('arrowleft')?1:0);dy+=(keys.has('arrowdown')?1:0)-(keys.has('arrowup')?1:0);}if(p.i===0&&clickTarget&&!dx&&!dy){dx=clickTarget.x-p.x;dy=clickTarget.y-p.y;if(Math.hypot(dx,dy)<12){clickTarget=null;dx=dy=0;}}else if(p.i===0&&(dx||dy))clickTarget=null;const len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;p.dx=dx;p.dy=dy;const speed=(state.upgrade?184:160)*(p.dash>0?3.1:1);const old={x:p.x,y:p.y};move(p,dx*speed*dt,dy*speed*dt,state);if(coop){const other=players[1-p.i];if(Math.hypot(other.x-p.x,other.y-p.y)>420){p.x=old.x;p.y=old.y;}}if(p.dash>0&&Math.random()<.5)burst(p.x,p.y,skin(p),1);}collect(p);for(const w of wisps)if(!w.stun&&Math.hypot(w.x-p.x,w.y-p.y)<27)damage(p);}
for(const w of wisps){w.stun=Math.max(0,w.stun-dt);if(w.stun)continue;let target=players.reduce((a,p)=>Math.hypot(p.x-w.x,p.y-w.y)<Math.hypot(a.x-w.x,a.y-w.y)?p:a,players[0]);if(Math.hypot(target.x-w.x,target.y-w.y)<210&&region(target.x)===region(w.x)){const a=Math.atan2(target.y-w.y,target.x-w.x);w.x+=Math.cos(a)*60*dt;w.y+=Math.sin(a)*60*dt;}else{w.x+=(w.ox+Math.sin(clock*.6+w.phase)*65-w.x)*dt;w.y+=(w.oy+Math.cos(clock*.5+w.phase)*90-w.y)*dt;}}
if(storm){storm.time-=dt;storm.spawn-=dt;if(storm.spawn<0){storm.spawn=.65;const p=players[Math.floor(Math.random()*players.length)];storm.hazards.push({x:p.x+(Math.random()-.5)*100,y:p.y+(Math.random()-.5)*100,t:1.15});}for(const h of storm.hazards){h.t-=dt;if(h.t<=0&&!h.fired){h.fired=true;burst(h.x,h.y,'#f58a73',20);for(const p of players)if(Math.hypot(p.x-h.x,p.y-h.y)<52)damage(p);if(!storm)break;}}if(storm){storm.hazards=storm.hazards.filter(h=>h.t>-.3);if(storm.time<=0){storm=null;state.won=true;state.coins+=40;save();updateHUD();show('EXPEDITION COMPLETE','<div class="reward">✦</div><h2>You brought back the sky.</h2><p>Memory. Generosity. Wisdom. You restored all three echoes and held back the storm.</p><p><strong>+40 sky shards · Keeper of the Sky unlocked</strong></p><p>Explore for remaining shards, try a new colour, or invite someone to a local co-op expedition.</p><button class="primary" id="afterWin">Keep exploring →</button>');$('#afterWin').onclick=close;}}}
particles=particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;return p.life>0;});pulses=pulses.filter(p=>{p.life-=dt;p.r+=260*dt;return p.life>0;});near=closest(players[0]);$('#interactPrompt').hidden=!near;$('#interact').textContent=near?`E · ${near.name}`:'E · Interact';const targetX=players.reduce((a,p)=>a+p.x,0)/players.length,targetY=players.reduce((a,p)=>a+p.y,0)/players.length;camera.x+=(targetX-camera.x)*Math.min(1,dt*7);camera.y+=(targetY-camera.y)*Math.min(1,dt*7);$('#zone').textContent=zones[region(players[0].x)];$('#energy').style.width=players[0].energy+'%';$('#hearts').textContent='◆ '.repeat(players[0].hearts)+(coop?' · P2 '+'◆'.repeat(players[1].hearts):'');$('#weather').textContent=storm?`STORM TRIAL · ${Math.ceil(storm.time)}s`:(state.won?'THE SKY IS WHOLE AGAIN':'THE REALM IS LISTENING');$('#time').textContent=`${Math.floor(state.seconds/60).toString().padStart(2,'0')}:${Math.floor(state.seconds%60).toString().padStart(2,'0')}`;}
function ellipse(x,y,rx,ry,col){ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();}
function line(points,col,width=1){ctx.strokeStyle=col;ctx.lineWidth=width;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();}
function diamond(x,y,size,col){ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(x,y-size);ctx.lineTo(x+size*.65,y);ctx.lineTo(x,y+size);ctx.lineTo(x-size*.65,y);ctx.closePath();ctx.fill();}
function label(text,x,y,col='#eaf5e8',size=11){ctx.font=`600 ${size}px system-ui`;ctx.textAlign='center';ctx.fillStyle='#081e2280';const width=ctx.measureText(text).width;ctx.fillRect(x-width/2-7,y-14,width+14,20);ctx.fillStyle=col;ctx.fillText(text,x,y);}
function tree(x,y,s=1,z=0){ellipse(x+8,y+12,40*s,14*s,'#051f293f');ctx.fillStyle=z===2?'#79696d':'#76503f';ctx.fillRect(x-7*s,y-52*s,14*s,57*s);line([[x,y-20*s],[x-22*s,y-64*s]],'#82614b',8*s);line([[x,y-30*s],[x+22*s,y-74*s]],'#82614b',7*s);const leaves=z===2?['#416670','#547d7e','#6b9490']:['#24594c','#33715a','#4a8765'];ellipse(x,y-65*s,48*s,26*s,leaves[0]);ellipse(x-25*s,y-75*s,31*s,23*s,leaves[1]);ellipse(x+26*s,y-82*s,35*s,25*s,leaves[1]);ellipse(x,y-92*s,33*s,25*s,leaves[2]);for(let i=0;i<3;i++)ellipse(x+(i-1)*22*s,y-(76+i%2*13)*s,3*s,3*s,'#d4c176');}
function building(b){ellipse(b.x+b.w/2+10,b.y+b.h+15,b.w*.64,27,'#10252266');ctx.fillStyle='#654d48';ctx.fillRect(b.x,b.y+20,b.w,b.h-20);ctx.fillStyle=b.c;ctx.fillRect(b.x-8,b.y-8,b.w+16,b.h-28);ctx.strokeStyle='#e1b78570';ctx.lineWidth=3;ctx.strokeRect(b.x+5,b.y+4,b.w-10,b.h-53);ctx.fillStyle='#182d32';ctx.fillRect(b.x+b.w/2-16,b.y+b.h-45,32,45);for(let i=0;i<3;i++){ctx.fillStyle=i%2?'#e7b956':'#448c84';ctx.fillRect(b.x-10+i*(b.w+20)/3,b.y+b.h-51,(b.w+20)/3,22);line([[b.x-10+i*(b.w+20)/3,b.y+b.h-51],[b.x-10+(i+1)*(b.w+20)/3,b.y+b.h-51]],'#fae0ac',2);}for(let i=0;i<4;i++)diamond(b.x+22+i*(b.w-44)/3,b.y+30,7,'#f2d2a188');}
function tortoise(x,y){ellipse(x,y+14,27,12,'#0a1d234d');ellipse(x,y,25,19,'#c8a34d');ellipse(x,y-3,22,17,'#47795b');for(const[dx,dy]of[[-13,-4],[0,-9],[13,-3],[-7,7],[9,6]])diamond(x+dx,y+dy,6,'#d3b65e');ellipse(x+29,y-2,10,9,'#c0b77f');ellipse(x+33,y-5,2,2,'#112d2e');for(const dx of [-15,15])ellipse(x+dx,y+15,6,4,'#a89e67');}
function human(x,y,col,face='#9c6241',moving=false){ellipse(x,y+16,17,7,'#071b2659');const walk=moving?Math.sin(clock*14)*5:0;line([[x-6,y+3],[x-7+walk,y+17]],'#162c3c',7);line([[x+6,y+3],[x+7-walk,y+17]],'#162c3c',7);ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(x-12,y-17);ctx.lineTo(x+12,y-17);ctx.lineTo(x+15,y+6);ctx.lineTo(x-15,y+6);ctx.closePath();ctx.fill();line([[x-11,y-12],[x+10,y+3]],'#ffe5a3',3);ellipse(x,y-24,10,11,face);ellipse(x,y-31,10,5,'#1b242a');line([[x-11,y-11],[x-19,y]],face,5);line([[x+11,y-11],[x+19,y-3]],face,5);}
const trees=Array.from({length:80},(_,i)=>({x:80+(i*327%2930),y:150+(i*239%1450),s:.65+(i%4)*.16})).filter(t=>!BUILDINGS.some(b=>Math.abs(t.x-(b.x+b.w/2))<130&&Math.abs(t.y-(b.y+b.h/2))<130)&&!SHRINES.some(s=>Math.hypot(t.x-s.x,t.y-s.y)<110)&&!(t.y>820&&t.y<1050)&&Math.abs(t.x-1030)>100&&Math.abs(t.x-2050)>100);
function draw(){ctx.clearRect(0,0,cw,ch);ctx.fillStyle='#132f36';ctx.fillRect(0,0,cw,ch);ctx.save();ctx.translate(cw/2,ch/2);ctx.scale(zoom,zoom);ctx.translate(-camera.x,-camera.y);
// Three connected districts. Earth, water and the sky.
ctx.fillStyle='#477359';ctx.fillRect(0,0,1030,HEIGHT);ctx.fillStyle='#386e67';ctx.fillRect(1030,0,1020,HEIGHT);ctx.fillStyle='#57717b';ctx.fillRect(2050,0,1050,HEIGHT);
for(let i=0;i<300;i++){const x=(i*197)%WIDTH,y=100+(i*379)%1500;ctx.fillStyle=['#93ba7a18','#b6d29318','#162e2a15'][i%3];ellipse(x,y,10+i%13,3+i%4,ctx.fillStyle);}
line([[70,940],[3030,940]],'#b19c75',125);line([[70,940],[3030,940]],'#d0ba8a',100);line([[550,940],[720,600]],'#c5ad7d',65);line([[1450,940],[1640,1130]],'#c5ad7d',65);line([[2330,940],[2510,590]],'#b6b0a0',65);line([[2650,940],[2820,1040]],'#b6b0a0',65);
for(const[gx,need]of[[1030,'memory'],[2050,'balance']]){ctx.fillStyle=gx===1030?'#247c85':'#344f75';ctx.fillRect(gx-62,0,124,HEIGHT);for(let i=0;i<30;i++){const y=i*60+Math.sin(clock+i)*6;line([[gx-45,y],[gx+10,y+3],[gx+40,y]],'#99ebe331',2);}ctx.fillStyle='#795a42';ctx.fillRect(gx-70,857,140,146);for(let y=865;y<1000;y+=15){line([[gx-73,y],[gx+73,y]],'#c39a68',10);}line([[gx-76,850],[gx+76,850]],'#f3cc8e',5);line([[gx-76,1010],[gx+76,1010]],'#f3cc8e',5);if(!state.relics.includes(need)){ctx.fillStyle='#c98df044';ctx.fillRect(gx-12,850,24,160);line([[gx,852],[gx,1008]],'#e0a4ff',5);label('RESTORE THE ECHO',gx,825,'#f8d3ff',10);}}
// Carved plazas and cloth-lined streets.
for(const s of SHRINES){ellipse(s.x,s.y+10,86,55,'#263d4655');ellipse(s.x,s.y+6,72,46,'#b8ad8b');ellipse(s.x,s.y+6,62,38,'#6c8a7d');for(let i=0;i<8;i++){const a=i*Math.PI/4;diamond(s.x+Math.cos(a)*57,s.y+6+Math.sin(a)*33,5,'#e9ce8b');}ctx.fillStyle='#576e69';ctx.fillRect(s.x-18,s.y-25,36,42);const bob=Math.sin(clock*2)*5;const glow=ctx.createRadialGradient(s.x,s.y-45,0,s.x,s.y-45,65);glow.addColorStop(0,state.relics.includes(s.id)?'#f6c35e80':'#7af5dc90');glow.addColorStop(1,'#5ddbcc00');ctx.fillStyle=glow;ctx.fillRect(s.x-65,s.y-110,130,130);diamond(s.x,s.y-45+bob,20,state.relics.includes(s.id)?'#f6c35e':'#92f4df');label(s.name,s.x,s.y+78,'#fff0c8',11);}
for(const b of BUILDINGS)building(b);for(const t of trees)tree(t.x,t.y,t.s,region(t.x));
// Market bunting and lanterns.
for(let i=0;i<7;i++){const x=200+i*100;ctx.fillStyle='#6d5045';ctx.fillRect(x,760,5,65);ellipse(x+2,760,9,12,'#edc267');const g=ctx.createRadialGradient(x,760,0,x,760,35);g.addColorStop(0,'#ffd46d55');g.addColorStop(1,'#ffd46d00');ctx.fillStyle=g;ctx.fillRect(x-35,725,70,70);if(i<6){line([[x,755],[x+50,775],[x+100,755]],'#c5a971',2);for(let k=1;k<4;k++){const tx=x+k*25,ty=755+Math.sin(k*Math.PI/4)*16;ctx.fillStyle=k%2?'#d48c62':'#57a498';ctx.beginPath();ctx.moveTo(tx-7,ty);ctx.lineTo(tx+7,ty);ctx.lineTo(tx,ty+17);ctx.fill();}}}
for(const s of SHARDS)if(!state.collected.includes(s.id)){const bob=Math.sin(clock*3+s.id)*4;ellipse(s.x,s.y+8,8,3,'#183a3655');diamond(s.x,s.y-3+bob,9,'#ffdb82');diamond(s.x-2,s.y-6+bob,3,'#fff7d1');}
// The final gate.
ellipse(2820,1050,95,55,'#28344477');for(const x of [2758,2870]){ctx.fillStyle='#c2b5aa';ctx.fillRect(x,963,17,92);ctx.fillStyle='#e2d4b0';ctx.fillRect(x-5,956,27,12);}ctx.strokeStyle=state.won?'#f6c35e':state.relics.length===3?'#b89aee':'#6e7889';ctx.lineWidth=15;ctx.beginPath();ctx.arc(2820,973,57,Math.PI,0);ctx.stroke();const g=ctx.createRadialGradient(2820,1005,4,2820,1005,62);g.addColorStop(0,state.won?'#ffd269aa':'#ac85f399');g.addColorStop(1,'#a38ee500');ctx.fillStyle=g;ctx.fillRect(2750,935,140,140);label('THE BROKEN SKY GATE',2820,1095,'#e0cfff',11);
for(const n of NPCS){if(n.type==='tortoise')tortoise(n.x,n.y);else human(n.x,n.y,['#efbb65','#d98b69','#a992d9'][region(n.x)]);label(n.name,n.x,n.y+39,'#d9e8df',10);ellipse(n.x,n.y-55,12,12,'#152d36');ctx.fillStyle='#e8d6a6';ctx.font='bold 14px system-ui';ctx.textAlign='center';ctx.fillText('…',n.x,n.y-52);}
for(const w of wisps){const bob=Math.sin(clock*4+w.phase)*7;ellipse(w.x,w.y+12,17,7,'#25334644');ellipse(w.x,w.y-8+bob,w.stun?9:15,17,w.stun?'#85789566':'#bc8ff0');ellipse(w.x-5,w.y-10+bob,3,3,'#f9f2ff');ellipse(w.x+5,w.y-10+bob,3,3,'#f9f2ff');}
if(storm)for(const h of storm.hazards){ctx.strokeStyle=h.t>0?'#ffad8a':'#ffd9a0';ctx.fillStyle=h.t>0?'#e36f593d':'#ffba7888';ctx.lineWidth=3;ctx.beginPath();ctx.arc(h.x,h.y,52,0,Math.PI*2);ctx.fill();ctx.stroke();if(h.t>0){ctx.beginPath();ctx.arc(h.x,h.y,52*(1-h.t/1.15),0,Math.PI*2);ctx.stroke();}}
for(const p of players){ctx.globalAlpha=p.inv>0&&Math.sin(clock*22)>0?.4:1;human(p.x,p.y,skin(p),'#a46c48',keys.size>0||!!clickTarget);ctx.globalAlpha=1;label(p.i?'P2':'YOU',p.x,p.y-48,skin(p),10);if(p.dash>0)ellipse(p.x-p.dx*23,p.y-p.dy*23,13,7,skin(p)+'66');}
for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);diamond(p.x,p.y,3,p.col);}ctx.globalAlpha=1;for(const p of pulses){ctx.strokeStyle=`rgba(116,240,220,${p.life})`;ctx.lineWidth=4;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.stroke();}
ctx.restore();drawCompass();drawMinimap();if(paused){ctx.fillStyle='#07161bb0';ctx.fillRect(0,0,cw,ch);ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='600 30px system-ui';ctx.fillText('Take a breath.',cw/2,ch/2);ctx.font='14px system-ui';ctx.fillText('Your adventure is paused. Press Escape or Resume.',cw/2,ch/2+35);}}
function drawCompass(){if(state.won||modal.open)return;const target=SHRINES.find(s=>!state.relics.includes(s.id))||{x:2820,y:1040,name:'Sky gate'};const p=players[0],dist=Math.hypot(target.x-p.x,target.y-p.y);if(dist<100)return;const a=Math.atan2(target.y-p.y,target.x-p.x),r=Math.min(cw*.25,ch*.27),x=cw/2+Math.cos(a)*r,y=ch/2+Math.sin(a)*r;ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#ffe29b';ctx.beginPath();ctx.moveTo(12,0);ctx.lineTo(-7,-7);ctx.lineTo(-3,0);ctx.lineTo(-7,7);ctx.fill();ctx.restore();ctx.textAlign='center';ctx.font='10px system-ui';ctx.fillStyle='#fff2c3';ctx.fillText(Math.round(dist)+' steps',x,y+22);}
function drawMinimap(){if(cw<500)return;const w=160,h=88,x=cw-w-24,y=80;ctx.fillStyle='#10232bd9';ctx.fillRect(x,y,w,h);ctx.strokeStyle='#b9d1c044';ctx.strokeRect(x,y,w,h);ctx.fillStyle='#867a5d';ctx.fillRect(x+3,y+46,w-6,5);for(const s of SHRINES){ctx.fillStyle=state.relics.includes(s.id)?'#f6c35e':'#5ddbcc';ctx.fillRect(x+s.x/WIDTH*w-2,y+s.y/HEIGHT*h-2,4,4);}for(const p of players){ctx.fillStyle=skin(p);ctx.beginPath();ctx.arc(x+p.x/WIDTH*w,y+p.y/HEIGHT*h,3,0,7);ctx.fill();}ctx.font='8px system-ui';ctx.fillStyle='#b6ccc9';ctx.textAlign='left';ctx.fillText('M · WORLD MAP',x+7,y+h+14);}
function frame(t){const dt=Math.min((t-last)/1000||.016,.04);last=t;if(running){if(!paused&&!modal.open)update(dt);draw();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
window.addEventListener('beforeunload',()=>{if(running)save();});
